properties.DashboardBody:
{
  "widgets": [
    {
      "type": "metric",
      "x": 0,
      "y": 0,
      "width": 12,
      "height": 6,
      "properties": {
        "title": "Event Ingestion Latency (P99) — SLO < 5000ms",
        "metrics": [
          ["FSxN-S3AP-Patterns", "EventIngestionLatency_ms", {"stat": "p99"}]
        ],
        "period": 300,
        "region": "us-east-1",
        "annotations": {
          "horizontal": [
            {"value": 5000, "label": "SLO Threshold", "color": "#d62728"}
          ]
        }
      }
    },
    {
      "type": "metric",
      "x": 12,
      "y": 0,
      "width": 12,
      "height": 6,
      "properties": {
        "title": "Processing Success Rate — SLO > 99.5%",
        "metrics": [
          ["FSxN-S3AP-Patterns", "ProcessingSuccessRate_pct", {"stat": "Average"}]
        ],
        "period": 300,
        "region": "us-east-1",
        "annotations": {
          "horizontal": [
            {"value": 99.5, "label": "SLO Threshold", "color": "#d62728"}
          ]
        }
      }
    },
    {
      "type": "metric",
      "x": 0,
      "y": 6,
      "width": 12,
      "height": 6,
      "properties": {
        "title": "FPolicy Reconnect Time — SLO < 30s",
        "metrics": [
          ["FSxN-S3AP-Patterns", "FPolicyReconnectTime_sec", {"stat": "Maximum"}]
        ],
        "period": 300,
        "region": "us-east-1",
        "annotations": {
          "horizontal": [
            {"value": 30, "label": "SLO Threshold", "color": "#d62728"}
          ]
        }
      }
    },
    {
      "type": "metric",
      "x": 12,
      "y": 6,
      "width": 12,
      "height": 6,
      "properties": {
        "title": "Replay Completion Time — SLO < 300s",
        "metrics": [
          ["FSxN-S3AP-Patterns", "ReplayCompletionTime_sec", {"stat": "Maximum"}]
        ],
        "period": 300,
        "region": "us-east-1",
        "annotations": {
          "horizontal": [
            {"value": 300, "label": "SLO Threshold", "color": "#d62728"}
          ]
        }
      }
    },
    {
      "type": "text",
      "x": 0,
      "y": 12,
      "width": 24,
      "height": 1,
      "properties": {
        "markdown": "## Synthetic Monitoring — S3AP & ONTAP Health (Feature 3 Integration)"
      }
    },
    {
      "type": "metric",
      "x": 0,
      "y": 13,
      "width": 12,
      "height": 6,
      "properties": {
        "title": "S3AP Latency (Synthetic Canary)",
        "metrics": [
          ["FSxN-S3AP-Patterns/Canary", "S3AP_ListLatency_ms", {"stat": "Average", "label": "List Latency"}],
          ["FSxN-S3AP-Patterns/Canary", "S3AP_GetLatency_ms", {"stat": "Average", "label": "Get Latency"}]
        ],
        "period": 300,
        "region": "us-east-1",
        "view": "timeSeries",
        "stacked": false
      }
    },
    {
      "type": "metric",
      "x": 12,
      "y": 13,
      "width": 12,
      "height": 6,
      "properties": {
        "title": "ONTAP Health Check (Synthetic Canary)",
        "metrics": [
          ["FSxN-S3AP-Patterns/Canary", "ONTAP_HealthCheck", {"stat": "Minimum", "label": "Health (1=OK, 0=Fail)"}]
        ],
        "period": 300,
        "region": "us-east-1",
        "view": "timeSeries",
        "stacked": false
      }
    },
    {
      "type": "alarm",
      "x": 0,
      "y": 19,
      "width": 24,
      "height": 3,
      "properties": {
        "title": "SLO Alarm Status",
        "alarms": [
          "${EventIngestionLatencyAlarm.Arn}",
          "${ProcessingSuccessRateAlarm.Arn}",
          "${ReconnectTimeAlarm.Arn}",
          "${ReplayCompletionTimeAlarm.Arn}"
        ]
      }
    }
  ]
}
